WITH e AS (SELECT *, ifNull(npc_name, '') AS name, multiIf(npc_id IS NULL, 'zone-in', npc_id < 16777216, 'self', 'npc') AS who FROM npc_events WHERE zone_id = {zone:Int64} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), p AS (SELECT who, name, event_id, arraySlice(arrayReverseSort(t -> t.k, groupArray((v, k, seen))), 1, 20) AS paramss, count() AS params_kinds FROM (SELECT who, name, event_id, params AS v, sum(n) AS k, argMax((capture_id, ts_ms), ts_ms) AS seen FROM e  GROUP BY who, name, event_id, v) GROUP BY who, name, event_id), o AS (SELECT who, name, event_id, arraySlice(arrayReverseSort(t -> t.k, groupArray((v, k, seen))), 1, 20) AS optionss, count() AS options_kinds FROM (SELECT who, name, event_id, options AS v, sum(n) AS k, argMax((capture_id, ts_ms), ts_ms) AS seen FROM e  GROUP BY who, name, event_id, v) GROUP BY who, name, event_id), x AS (SELECT who, name, event_id, arraySlice(arrayReverseSort(t -> t.k, groupArray((v, k, seen))), 1, 20) AS followed_bys, count() AS followed_by_kinds FROM (SELECT who, name, event_id, followed_by AS v, sum(n) AS k, argMax((capture_id, ts_ms), ts_ms) AS seen FROM e WHERE followed_by IS NOT NULL GROUP BY who, name, event_id, v) GROUP BY who, name, event_id) SELECT a.who AS who, a.name AS npc_name, a.event_id AS event_id, a.n AS n, a.captures AS captures, a.ids AS ids, p.paramss AS params, p.params_kinds AS params_kinds, o.optionss AS options, o.options_kinds AS options_kinds, x.followed_bys AS followed_by, z.name AS zone_name FROM (SELECT who, name, event_id, sum(n) AS n, uniqExact(capture_id) AS captures, arraySort(groupUniqArray((npc_id, release))) AS ids FROM e GROUP BY ALL) a LEFT JOIN p USING (who, name, event_id) LEFT JOIN o USING (who, name, event_id) LEFT JOIN x USING (who, name, event_id) LEFT JOIN (SELECT id, any(name) AS name FROM zone_names GROUP BY id) z ON z.id = {zone:Int64} ORDER BY who = 'npc', npc_name, event_id
